import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"核心概念","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/concepts.md","filePath":"getting-started/concepts.md","lastUpdated":1794391755000}`),a={name:`getting-started/concepts.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h1><p>这一页把框架的核心概念一次讲清：特性与清单、能力图谱、执行管道、操作契约、默认实现与 Provider、结果与错误、环层与命名。它是后面所有章节的词汇表。读完<a href="/getting-started/first-app">第一个应用</a>再读这一页效果最好，因为每个概念你都已经在代码里碰过。</p><h2 id="一张图" tabindex="-1">一张图 <a class="header-anchor" href="#一张图" aria-label="Permalink to “一张图”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP 请求 / gRPC 调用 / MCP tools/call / 命令行 / 消息投递 / 作业触发 / 插件回调</span></span>
<span class="line"><span>   │  协议适配器或派发器构造 InvocationContext，把线上消息翻译成操作请求</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Ingress → Observe → Resilience → Authenticate → Tenant → Authorize</span></span>
<span class="line"><span>        → Validate → Idempotency → Transaction → Handle → Egress</span></span>
<span class="line"><span>   │  Handle 阶段执行操作，操作经子系统抽象访问 Provider</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Egress：Result 与 Error 翻译回协议（HTTP 为 RFC 9457 Problem Details，gRPC 为状态码与尾部元数据）</span></span></code></pre></div><p>应用由若干特性组成，特性在启动前被内核装配成一张能力图谱；运行时每次调用都走同一条管道；业务在 Handle 阶段以操作的形式执行；横切能力由子系统提供，子系统的实现可以替换。</p><h2 id="特性与清单" tabindex="-1">特性与清单 <a class="header-anchor" href="#特性与清单" aria-label="Permalink to “特性与清单”">​</a></h2><p>特性是实现 <code>IFeature</code> 的类，是内核装配的最小单元。它只有两个成员：一份清单 <code>Manifest</code>，一个 <code>Configure(FeatureContext)</code> 方法。清单写明这个特性是谁、提供哪些能力、依赖哪些能力、贡献了什么；<code>Configure</code> 在构建期被调用一次，用来显式注册服务、中间件、权限与操作。</p><p>特性没有基类、没有生命周期钩子，内核也不扫描程序集。应用用 <code>UseFeature&lt;T&gt;()</code> 显式加入每一个特性。需要在启动与停止时做事的特性实现 <code>IHostedFeature</code>。</p><p>能力包是包含一个或多个特性的 NuGet 包。框架里每个子系统的默认实现与 Provider 都是能力包；应用自己的业务模块也写成能力包。详见<a href="/startup/features">特性与清单</a>。</p><h2 id="能力-id-与能力图谱" tabindex="-1">能力 ID 与能力图谱 <a class="header-anchor" href="#能力-id-与能力图谱" aria-label="Permalink to “能力 ID 与能力图谱”">​</a></h2><p>依赖按能力声明，不按包名或类型。能力 ID 的形式是 <code>&lt;领域&gt;.&lt;能力&gt;</code>，引用时带接口版本，如 <code>persistence.relational@1</code>、<code>caching.distributed@1</code>。同一能力可以由多个 Provider 提供：<code>persistence.relational</code> 可以来自 <code>Persistence.InMemory</code>、<code>Persistence.EntityFrameworkCore</code> 或 <code>Persistence.SqlSugar</code>。</p><p>内核在构建期收集全部清单，按版本范围求解，拓扑排序，生成已解析图。缺失依赖、循环、版本冲突、同一能力有多个候选都会带着双方信息报错；启动日志与 <code>graph</code> 命令打印同一份图。同一能力有多个 Provider 时，默认实现（清单 <code>role: default</code>）自动让位；两个以上显式 Provider 时，在配置里指定。详见<a href="/startup/capabilities">能力图谱与 Provider</a>。</p><h2 id="执行管道" tabindex="-1">执行管道 <a class="header-anchor" href="#执行管道" aria-label="Permalink to “执行管道”">​</a></h2><p>每次调用都经过一条固定十一个阶段的管道：</p><table tabindex="0"><thead><tr><th>阶段</th><th>职责</th><th>谁提供中间件</th></tr></thead><tbody><tr><td>Ingress</td><td>协议消息归一化、大小限制</td><td>内核</td></tr><tr><td>Observe</td><td>Trace、日志、指标、审计</td><td>内核、审计子系统</td></tr><tr><td>Resilience</td><td>截止时间、限流、并发上限、熔断</td><td>内核</td></tr><tr><td>Authenticate</td><td>主体解析</td><td>安全子系统</td></tr><tr><td>Tenant</td><td>租户解析与分片</td><td>多租户子系统</td></tr><tr><td>Authorize</td><td>权限与策略判定</td><td>安全子系统</td></tr><tr><td>Validate</td><td>契约校验</td><td>内核，由操作 Schema 驱动</td></tr><tr><td>Idempotency</td><td>幂等键去重</td><td>缓存子系统</td></tr><tr><td>Transaction</td><td>工作单元</td><td>持久化子系统</td></tr><tr><td>Handle</td><td>调用操作</td><td>内核</td></tr><tr><td>Egress</td><td>结果与错误翻译</td><td>协议适配器</td></tr></tbody></table><p>特性按阶段插入中间件，不需要知道其他中间件。排序规则是「阶段、阶段内的 Before 与 After 约束、归属清单 ID」，结果确定且可打印。管道不绑定 HTTP：Web、命令行、消息消费、作业与插件回调走同一条管道。详见<a href="/startup/pipeline">执行管道</a>。</p><h2 id="调用上下文" tabindex="-1">调用上下文 <a class="header-anchor" href="#调用上下文" aria-label="Permalink to “调用上下文”">​</a></h2><p>管道上下文是 <code>InvocationContext</code>，携带取消令牌、截止时间、W3C Trace、已登记的 Baggage 键（租户、主体、关联 ID、幂等键、区域）、作用域对象袋与作用域服务。安全上下文（主体、租户）由 Authenticate 与 Tenant 阶段写入，之后不可变。详见<a href="/startup/invocation-context">调用上下文</a>。</p><h2 id="操作契约" tabindex="-1">操作契约 <a class="header-anchor" href="#操作契约" aria-label="Permalink to “操作契约”">​</a></h2><p>业务以操作为单位声明：一个类实现 <code>IOperation&lt;TRequest, TResponse&gt;</code> 并标注 <code>[Operation]</code>。操作 ID 的形式是 <code>&lt;资源复数&gt;.&lt;动词&gt;</code>，如 <code>orders.create</code>。源生成器从契约产出登记代码与请求、响应的 JSON Schema；协议适配器把 HTTP 请求、gRPC 调用、MCP 的 <code>tools/call</code> 与命令行参数翻译成同一种调用。</p><table tabindex="0"><thead><tr><th>操作 ID</th><th>HTTP</th><th>gRPC</th><th>MCP tool</th><th>命令行</th></tr></thead><tbody><tr><td><code>orders.create</code></td><td><code>POST /orders</code></td><td><code>Orders/Create</code></td><td><code>orders_create</code></td><td><code>orders create</code></td></tr><tr><td><code>orders.get</code></td><td><code>GET /orders/{id}</code></td><td><code>Orders/Get</code></td><td><code>orders_get</code></td><td><code>orders get</code></td></tr><tr><td><code>orders.list</code></td><td><code>GET /orders</code></td><td><code>Orders/List</code></td><td><code>orders_list</code></td><td><code>orders list</code></td></tr></tbody></table><p>授权要求与错误码在各协议上一致。详见<a href="/web/operations">操作契约</a>。</p><h2 id="默认实现与-provider" tabindex="-1">默认实现与 Provider <a class="header-anchor" href="#默认实现与-provider" aria-label="Permalink to “默认实现与 Provider”">​</a></h2><p>每个子系统有一个抽象包 <code>&lt;领域&gt;.Abstractions</code>，配一个零外部依赖、容量有界的默认实现（<code>InMemory</code>、<code>FileSystem</code>），再由 Provider 包接入 EF Core、SqlSugar、Redis、RabbitMQ、Kafka、S3 等外部设施。</p><table tabindex="0"><thead><tr><th>角色</th><th>包名形式</th><th>示例</th></tr></thead><tbody><tr><td>抽象</td><td><code>&lt;领域&gt;.Abstractions</code></td><td><code>Caching.Abstractions</code></td></tr><tr><td>默认实现</td><td>按机制命名</td><td><code>Caching.InMemory</code>、<code>ObjectStorage.FileSystem</code></td></tr><tr><td>经持久化子系统的 Provider</td><td><code>&lt;领域&gt;.Database</code></td><td><code>Security.Database</code></td></tr><tr><td>接外部设施的 Provider</td><td>按技术命名</td><td><code>Caching.Redis</code>、<code>Persistence.EntityFrameworkCore</code></td></tr><tr><td>一致性套件</td><td><code>&lt;领域&gt;.Conformance</code></td><td><code>Caching.Conformance</code></td></tr></tbody></table><p>「默认」是清单里的角色，不是包名。换 Provider 只加包、加一行 <code>UseFeature</code>，业务代码不变；默认实现与 Provider 通过同一套一致性套件。</p><h2 id="结果与错误" tabindex="-1">结果与错误 <a class="header-anchor" href="#结果与错误" aria-label="Permalink to “结果与错误”">​</a></h2><p>可恢复的失败用 <code>Result</code> 与 <code>Error</code> 表达，不抛异常。错误码的形式是 <code>&lt;领域大写&gt;_&lt;KIND&gt;_&lt;三位序号&gt;</code>，如 <code>PERSISTENCE_CONFLICT_001</code>、<code>SECURITY_DENIED_004</code>；KIND 决定 HTTP 状态码、gRPC 状态与命令行退出码。<code>Error</code> 只携带消息键与参数，宿主在 Egress 阶段按调用方的区域翻译成文案。配置与编程错误才抛异常。详见<a href="/web/errors">结果与错误处理</a>。</p><h2 id="本地化" tabindex="-1">本地化 <a class="header-anchor" href="#本地化" aria-label="Permalink to “本地化”">​</a></h2><p>面向人的文案不写在代码里。代码只引用消息键常量，每种语言一个文件 <code>Localization/&lt;区域&gt;.json</code>，内置十种区域，默认 <code>en-US</code>。取文案用 <code>key.L()</code>，按当前调用的区域渲染。详见<a href="/common/localization">全球化和本地化</a>。</p><h2 id="环层与依赖规则" tabindex="-1">环层与依赖规则 <a class="header-anchor" href="#环层与依赖规则" aria-label="Permalink to “环层与依赖规则”">​</a></h2><p>包按环层组织，依赖只能指向更低的环，同环之间只经抽象包往来，规则由架构测试执行：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ring 6  组合包          Profiles.Minimal / Standard / Full</span></span>
<span class="line"><span>Ring 5  协议与插件      Protocols.* / Plugins.InProcess / OutOfProcess / Wasm</span></span>
<span class="line"><span>Ring 4  宿主            Hosting.AspNetCore / Hosting.CommandLine</span></span>
<span class="line"><span>Ring 3  实现            &lt;领域&gt;.InMemory、&lt;领域&gt;.Database、Redis、EntityFrameworkCore 等</span></span>
<span class="line"><span>Ring 2  抽象            Domain、&lt;领域&gt;.Abstractions</span></span>
<span class="line"><span>Ring 1  内核            Kernel</span></span>
<span class="line"><span>Ring 0  原语层          Primitives</span></span>
<span class="line"><span>工具链                  Kernel.Analyzers、Kernel.Generators、Persistence.Generators、</span></span>
<span class="line"><span>                        &lt;领域&gt;.Conformance、Testing、Cli</span></span></code></pre></div><p>原语层不引用任何包；内核与全部抽象包只允许 <code>Microsoft.Extensions.*</code> 抽象包；原语层与内核零反射，反射只允许出现在 <code>Plugins.InProcess</code>。</p><h2 id="命名约定" tabindex="-1">命名约定 <a class="header-anchor" href="#命名约定" aria-label="Permalink to “命名约定”">​</a></h2><p>命名由术语表推出，架构测试校验：</p><table tabindex="0"><thead><tr><th>对象</th><th>规则</th><th>示例</th></tr></thead><tbody><tr><td>包 ID</td><td><code>XiHan.Framework.&lt;领域&gt;[.&lt;角色&gt;]</code></td><td><code>XiHan.Framework.Caching.Redis</code></td></tr><tr><td>命名空间</td><td>等于包 ID，子命名空间最多一层</td><td><code>XiHan.Framework.Caching.Abstractions.Locking</code></td></tr><tr><td>能力 ID</td><td><code>&lt;领域小写&gt;.&lt;能力&gt;</code>，引用时带接口版本</td><td><code>caching.distributed@1</code></td></tr><tr><td>清单 ID</td><td><code>xihan.&lt;领域&gt;.&lt;名称&gt;</code></td><td><code>xihan.caching.redis</code></td></tr><tr><td>配置节</td><td><code>XiHan:&lt;领域&gt;</code></td><td><code>XiHan:Caching</code></td></tr><tr><td>错误码</td><td><code>&lt;领域大写&gt;_&lt;KIND&gt;_&lt;三位序号&gt;</code></td><td><code>PERSISTENCE_CONFLICT_001</code></td></tr><tr><td>操作 ID</td><td><code>&lt;资源复数&gt;.&lt;动词&gt;</code></td><td><code>orders.create</code></td></tr><tr><td>消息键</td><td><code>&lt;领域&gt;.&lt;资源&gt;.&lt;键&gt;</code></td><td><code>security.token.subject_missing</code></td></tr></tbody></table><p>类型名不带 <code>XiHan</code> 前缀；<code>Default</code>、<code>Core</code>、<code>Common</code>、<code>Manager</code>、<code>Helper</code> 等词不进包名与领域名。</p><h2 id="稳定性分级" tabindex="-1">稳定性分级 <a class="header-anchor" href="#稳定性分级" aria-label="Permalink to “稳定性分级”">​</a></h2><p>公开类型都带 <code>[ApiLevel(Stability, &lt;引入版本&gt;)]</code>，公开面以各包的 <code>PublicAPI.Shipped.txt</code> 与 <code>PublicAPI.Unshipped.txt</code> 为准：</p><table tabindex="0"><thead><tr><th>级别</th><th>含义</th></tr></thead><tbody><tr><td><code>Stable</code></td><td>大版本内不破坏</td></tr><tr><td><code>Preview</code></td><td>小版本可能变更，补丁版本不变；每次变更都在更新日志写明迁移方式</td></tr><tr><td><code>Experimental</code></td><td>小版本可能变更或移除，用于收集反馈</td></tr><tr><td><code>Internal</code></td><td>不对外承诺，分析器阻止外部引用</td></tr><tr><td><code>Deprecated</code></td><td>将在下一个大版本移除</td></tr></tbody></table><p>级别在同一大版本内只升不降，<code>Stable</code> 的成员不依赖 <code>Preview</code> 或 <code>Experimental</code> 的类型，也不声明可选参数（重载或选项记录代替）；这两条由分析器 XH0006 与 XH0008 在编译期检查。要求升级时不改代码，就只用 <code>Stable</code> 的 API。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/getting-started/profiles">组合包与选包</a>：Minimal、Standard、Full 各含什么</li><li><a href="/startup/bootstrap">装配入口</a>：从 <code>AddXiHan</code> 开始系统学习</li></ul>`,44)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};